import{_ as d,o,c as r,a2 as a}from"./chunks/framework.BLqL3B_z.js";const b=JSON.parse('{"title":"第 1 章 初识 WorkBuddy","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 你大概听过\\"AI 助手\\"很多次，但 WorkBuddy 不太一样：它不是让你去学提示词， 而是给你一个能直接干活的工作台。这一章用大白话讲清楚它到底是什么、 能帮你做什么、以及你该用什么样的预期去用它。","frontmatter":{"title":"第 1 章 初识 WorkBuddy"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md","lastUpdated":1791269833000}'),e={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 1 章 初识 WorkBuddy/index.md"};function u(l,t,n,i,s,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="第-1-章-初识-workbuddy" tabindex="-1">第 1 章 初识 WorkBuddy <a class="header-anchor" href="#第-1-章-初识-workbuddy" aria-label="Permalink to &quot;第 1 章 初识 WorkBuddy&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>你大概听过&quot;AI 助手&quot;很多次，但 WorkBuddy 不太一样：它不是让你去学提示词， 而是给你一个<strong>能直接干活的工作台</strong>。这一章用大白话讲清楚它到底是什么、 能帮你做什么、以及你该用什么样的预期去用它。</p><h2 id="一、一句话说清-workbuddy-是什么" tabindex="-1">一、一句话说清 WorkBuddy 是什么 <a class="header-anchor" href="#一、一句话说清-workbuddy-是什么" aria-label="Permalink to &quot;一、一句话说清 WorkBuddy 是什么&quot;">​</a></h2><p>WorkBuddy 是一个 <strong>AI Agent（智能体）办公工作台</strong>：你用自然语言下任务， 它自己拆步骤、调工具、出结果。常见工具包括写代码、读文件、上网查资料、 连外部服务（邮箱、文档、数据库等）。</p><p><strong>和&quot;聊天机器人&quot;的区别</strong>：聊天机器人主要陪你聊；WorkBuddy 能<strong>动手</strong>—— 改文件、跑脚本、发邮件、生成文档，并把结果落到你的电脑或云端。</p><h2 id="二、它能帮你做的-4-类事" tabindex="-1">二、它能帮你做的 4 类事 <a class="header-anchor" href="#二、它能帮你做的-4-类事" aria-label="Permalink to &quot;二、它能帮你做的 4 类事&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>举例</th><th>你得到的</th></tr></thead><tbody><tr><td>写东西</td><td>写周报、改文案、出方案</td><td>一份可直接用的文档</td></tr><tr><td>处理文件</td><td>整理桌面、批量重命名、提取表格</td><td>干净的文件系统 / Excel</td></tr><tr><td>联网办事</td><td>查资料、盯资讯、填表单</td><td>汇总好的信息或已完成的动作</td></tr><tr><td>自动跑</td><td>每周一发周报、每天抓新闻</td><td>不用你操心，到点出活</td></tr></tbody></table><h2 id="三、第一次打开-你会看到什么" tabindex="-1">三、第一次打开，你会看到什么 <a class="header-anchor" href="#三、第一次打开-你会看到什么" aria-label="Permalink to &quot;三、第一次打开，你会看到什么&quot;">​</a></h2><p>打开后最左边是<strong>导航栏</strong>（下一章细讲），中间是任务区。你大部分时间都在 &quot;新建任务 → 描述需求 → 看它执行 → 收结果&quot;这个循环里。</p><h2 id="四、新手最常见的-3-个预期误区" tabindex="-1">四、新手最常见的 3 个预期误区 <a class="header-anchor" href="#四、新手最常见的-3-个预期误区" aria-label="Permalink to &quot;四、新手最常见的 3 个预期误区&quot;">​</a></h2><ol><li><strong>&quot;它什么都能做&quot;</strong> —— 不能。它擅长有明确输入输出、能拆步骤的任务； 纯创意拍板、需要真人担责的事，它只能辅助。</li><li><strong>&quot;说一句就行&quot;</strong> —— 说清楚&quot;要什么 + 给什么 + 交付成什么样&quot;三要素，结果才好。</li><li><strong>&quot;出错就废了&quot;</strong> —— 它可以回滚、重试、分步确认；把大任务拆小，风险可控。</li></ol><h2 id="五、本章任务清单-做完就算过关" tabindex="-1">五、本章任务清单（做完就算过关） <a class="header-anchor" href="#五、本章任务清单-做完就算过关" aria-label="Permalink to &quot;五、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 能用自己的话解释 WorkBuddy 和聊天机器人的区别</li><li>[ ] 想好你第一个想让它帮你做的任务是什么</li><li>[ ] 打开软件，认出左侧导航栏（下章细讲）</li></ul><hr><p><em>下一篇：第 2 章 下载、安装、登录与更新——把它装到你的电脑上。</em></p>',16)])])}const c=d(e,[["render",u]]);export{b as __pageData,c as default};
